package main
import ("fmt"; "github.com/monkukui/ac-library-go/dsu")
func main(){d:=dsu.New(3);d.Merge(0,1);if d.Size(0)!=2 {panic("dsu")};fmt.Println(3)}

package main
import ("fmt"; "golang.org/x/exp/slices")
func main(){s:=[]int{2,1};slices.Sort(s);if s[0]!=1{panic("sort")};fmt.Println(3)}

package main
import("fmt";"os";"syscall")
func main(){f,e:=os.Create("lock-probe");if e!=nil{panic(e)};defer f.Close();if syscall.Flock(int(f.Fd()),syscall.LOCK_EX|syscall.LOCK_NB)!=syscall.ENOSYS{panic("file locking must remain blocked during execution")};fmt.Println(3)}

