import neo
let x=vector([1.0,2.0])
let y=vector([1.0,1.0])
doAssert x*y == 3.0
echo 3

{.emit: """
#include <atcoder/dsu>
int library_smoke(){atcoder::dsu d(3); d.merge(0,1); return d.size(0)==2;}
""".}
proc library_smoke(): cint {.importcpp: "library_smoke()",nodecl.}
doAssert library_smoke()==1
echo 3

{.emit: """
#include <Eigen/Dense>
int library_smoke(){Eigen::Vector2d v(1,2); return v.sum()==3;}
""".}
proc library_smoke(): cint {.importcpp: "library_smoke()",nodecl.}
doAssert library_smoke()==1
echo 3

{.emit: """
#include <boost/version.hpp>
#include <boost/multiprecision/cpp_int.hpp>
int library_smoke(){boost::multiprecision::cpp_int x=1; x+=2; return BOOST_VERSION==108800 && x==3;}
""".}
proc library_smoke(): cint {.importcpp: "library_smoke()",nodecl.}
doAssert library_smoke()==1
echo 3

{.passL: "-lgmp".}
{.emit: """
#include <gmp.h>
int library_smoke(){mpz_t x;mpz_init_set_ui(x,3);int ok=mpz_cmp_ui(x,3)==0;mpz_clear(x);return ok;}
""".}
proc library_smoke(): cint {.importcpp: "library_smoke()",nodecl.}
doAssert library_smoke()==1
echo 3

{.passL: "-lmpfr -lgmp".}
{.emit: """
#include <mpfr.h>
int library_smoke(){mpfr_t x;mpfr_init2(x,128);mpfr_set_ui(x,3,MPFR_RNDN);int ok=mpfr_cmp_ui(x,3)==0;mpfr_clear(x);return ok;}
""".}
proc library_smoke(): cint {.importcpp: "library_smoke()",nodecl.}
doAssert library_smoke()==1
echo 3

{.passL: "-lfftw3".}
{.emit: """
#include <fftw3.h>
int library_smoke(){double x[2]={1,2},y[2];fftw_plan p=fftw_plan_r2r_1d(2,x,y,FFTW_R2HC,FFTW_ESTIMATE);fftw_execute(p);int ok=y[0]==3;fftw_destroy_plan(p);return ok;}
""".}
proc library_smoke(): cint {.importcpp: "library_smoke()",nodecl.}
doAssert library_smoke()==1
echo 3

javascript-node24-isolate.source:
import { DSU } from "ac-library-js";
import { Stack } from "data-structure-typed";
import { List } from "immutable";
import lodash from "lodash";
import { add } from "mathjs";
import { Vector } from "tstl";
const d=new DSU(3); d.merge(0,1);
const s=new Stack(); s.push(3);
const v=new Vector(); v.push_back(3);
if(d.size(0)!==2||s.pop()!==3||List([1,2]).reduce((a,b)=>a+b,0)!==3||lodash.sum([1,2])!==3||Number(add(1,2))!==3||v.at(0)!==3)throw new Error("library");
console.log(3);

